class Solution:
    def maxSubarrayLength(self, nums: List[int], k: int) -> int:
        cnt = collections.defaultdict(int)
        l = 0
        best = 0

        for r in range(len(nums)):
            cnt[nums[r]] += 1

            while cnt[nums[r]] > k:
                cnt[nums[l]] -= 1
                if cnt[nums[l]] <= 0:
                    cnt.pop(nums[l])
                l += 1

            best = max(best, r - l + 1)

        return best
